                coreIdea: '**转发（forwarding）**：把分组从路由器的输入端口移到合适的输出端口——是**本地动作**，由**本地转发表（local forwarding table）**决定，粒度是每个分组（microseconds–milliseconds）。**路由（routing）**：决定分组从源到目的所走的路径——是**全局过程**，由**路由算法（routing algorithm）**计算，时间尺度是秒级。',
