                coreIdea: '**流量强度（traffic intensity）** $\\rho = La/R$：到达率与链路服务率之比。它把"负载"无量纲化——**ρ 越接近 1，排队时延越急剧膨胀**。',
                mechanism: '$R$ = 链路带宽（bps），$L$ = 分组长度（bit），$a$ = 平均分组到达率（分组/秒）。于是 $La$ 是**比特到达率**（bit/s），与链路速率 $R$ 直接可比。三种情形：① **$La/R \\sim 0$**：排队时延很小；② **$La/R \\to 1$**：时延变得很大；③ **$La/R > 1$**：到达的"工作量"多于链路能服务的量，**平均时延趋于无穷**。',
                comparison: '这个"三个情形"就是拥塞的完整判据。**ρ < 1 时系统是稳定的**（服务能力大于到达率），但当 ρ 逼近 1 时排队时延不是线性增长而是**急剧上升**（排队论中的 $1/(1-\\rho)$ 量级）；**ρ ≥ 1 时队列持续增长**，缓冲区最终填满导致丢包（k1.4.6），且**平均时延发散**。这解释了为什么"带宽利用率"不能无限逼近 100%——运营者必须留出余量来吸收突发流量。',
